import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    orders_info = {}  # id -> {'side','price','qty','arrival','active','type'}
    arrival_counter = 0

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            if oid in orders_info and orders_info[oid]['active'] and orders_info[oid]['qty'] > 0:
                orders_info[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        arrival = arrival_counter
        arrival_counter += 1
        orders_info[oid] = {
            'side': side,
            'price': price,
            'qty': qty,
            'arrival': arrival,
            'active': True,
            'type': typ
        }

        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                sp, sarr, sid = sell_heap[0]
                sinfo = orders_info[sid]
                if not sinfo['active'] or sinfo['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ == 'market' or price is None:
                    ok = True
                else:
                    ok = sp <= price
                if not ok:
                    break
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] == 0:
                    sinfo['active'] = False
                    heapq.heappop(sell_heap)

            orders_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                orders_info[oid]['active'] = False

        else:  # sell
            while remaining > 0 and buy_heap:
                neg_bp, barr, bid = buy_heap[0]
                bp = -neg_bp
                binfo = orders_info[bid]
                if not binfo['active'] or binfo['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ == 'market' or price is None:
                    ok = True
                else:
                    ok = bp >= price
                if not ok:
                    break
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] == 0:
                    binfo['active'] = False
                    heapq.heappop(buy_heap)

            orders_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(sell_heap, (price, arrival, oid))
            else:
                orders_info[oid]['active'] = False

    return trades

